import './App.css';
import { useState } from 'react';

function App() {
  const [ count, setCount ] = useState(0);

  function handleAdd()
  {
    // count = count + 1;
    console.log(count);
    setCount(count + 1);
  }


  return (
    <div className="App">

      <div className='box'>

        <p>{count}</p>
        <button onClick={handleAdd} className='add' >ADD</button>
        <button className='sub'>SUB</button>


      </div>

    </div>
  );
}

export default App;
